from __future__ import annotations

import asyncio
import signal
from typing import Awaitable, Callable


async def run_tasks(
    tasks: list[Callable[[], Awaitable[None]]],
    max_concurrent: int,
) -> None:
    if not tasks:
        return
    if max_concurrent <= 0:
        raise ValueError('max_concurrent must be positive')

    loop = asyncio.get_running_loop()
    semaphore = asyncio.Semaphore(max_concurrent)
    interrupted = asyncio.Event()

    used_loop_handler = False
    previous_handler = None
    try:
        loop.add_signal_handler(signal.SIGINT, interrupted.set)
        used_loop_handler = True
    except (NotImplementedError, RuntimeError):
        previous_handler = signal.signal(
            signal.SIGINT, lambda *args: interrupted.set()
        )

    async def wrap(task: Callable[[], Awaitable[None]]) -> None:
        async with semaphore:
            await task()

    runners = [asyncio.create_task(wrap(t)) for t in tasks]
    stopper = asyncio.create_task(interrupted.wait())
    cancelled = False
    try:
        await asyncio.wait(
            runners + [stopper],
            return_when=asyncio.FIRST_EXCEPTION,
        )
    except asyncio.CancelledError:
        cancelled = True
        raise
    finally:
        first_exc = None
        for runner in runners:
            if runner.done() and not runner.cancelled():
                exc = runner.exception()
                if exc is not None:
                    first_exc = exc
                    break

        if not stopper.done():
            stopper.cancel()
            try:
                await stopper
            except asyncio.CancelledError:
                pass

        if cancelled or interrupted.is_set() or first_exc is not None:
            for runner in runners:
                if not runner.done():
                    runner.cancel()

        await asyncio.gather(*runners, return_exceptions=True)
        if not cancelled:
            if interrupted.is_set():
                raise KeyboardInterrupt
            if first_exc is not None:
                raise first_exc

    if used_loop_handler:
        try:
            loop.remove_signal_handler(signal.SIGINT)
        except (NotImplementedError, RuntimeError):
            pass
    elif previous_handler is not None:
        signal.signal(signal.SIGINT, previous_handler)
